// aim.cpp
// Projects entity head positions to screen and returns a smoothed crosshair
// delta inside a 240px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /link user32.lib gdi32.lib
//
// Exported surface:
//   AimInit          – call once after the game window is known
//   AimUpdate        – call each frame; fills AimResult with smoothed delta
//   AimShutdown      – release resources

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <math.h>
#include <stdint.h>
#include <float.h>

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

struct Vec3 { float x, y, z; };

struct AimEntity {
    Vec3  headWorld;   // head bone position in world space
    bool  alive;       // skip dead / invisible entities
};

struct AimResult {
    float dx;          // pixels to move crosshair right  (negative = left)
    float dy;          // pixels to move crosshair down   (negative = up)
    bool  hasTarget;   // false when no entity is inside the cone
};

// ---------------------------------------------------------------------------
// Internal state
// ---------------------------------------------------------------------------

static struct AimState {
    // Camera / projection parameters set by AimInit
    float    fovYRad;
    float    screenW;
    float    screenH;
    HWND     hwnd;

    // 4×4 view-projection matrix (row-major, left-hand clip space)
    float    vp[16];

    // Smooth-step state
    float    smoothDx;
    float    smoothDy;

    // Configuration
    float    coneRadiusPx;    // default 120 → diameter 240 px
    float    smoothFactor;    // 0 = instant, 1 = never moves; default 0.12f
    bool     initialised;
} g;

// ---------------------------------------------------------------------------
// Matrix helpers (row-major)
// ---------------------------------------------------------------------------

static void MatMulVec4(const float m[16], float x, float y, float z, float w,
                       float *ox, float *oy, float *oz, float *ow)
{
    *ox = m[0]*x + m[1]*y + m[2]*z + m[3]*w;
    *oy = m[4]*x + m[5]*y + m[6]*z + m[7]*w;
    *oz = m[8]*x + m[9]*y + m[10]*z + m[11]*w;
    *ow = m[12]*x + m[13]*y + m[14]*z + m[15]*w;
}

// ---------------------------------------------------------------------------
// World → screen projection
// Returns false when behind the camera (w ≤ 0).
// ---------------------------------------------------------------------------

static bool WorldToScreen(Vec3 world, float *sx, float *sy)
{
    float cx, cy, cz, cw;
    MatMulVec4(g.vp, world.x, world.y, world.z, 1.0f, &cx, &cy, &cz, &cw);

    if (cw <= 0.0f) return false;

    float ndcX =  cx / cw;
    float ndcY = -cy / cw;   // flip Y so +Y is down on screen

    *sx = (ndcX + 1.0f) * 0.5f * g.screenW;
    *sy = (ndcY + 1.0f) * 0.5f * g.screenH;
    return true;
}

// ---------------------------------------------------------------------------
// Smooth-step interpolation toward (targetDx, targetDy).
// Uses an exponential approach: each frame the gap shrinks by (1-factor).
// ---------------------------------------------------------------------------

static void SmoothToward(float targetDx, float targetDy,
                          float *outDx,   float *outDy)
{
    float f = g.smoothFactor;
    // clamp to [0,1) so we never overshoot or freeze
    if (f < 0.0f) f = 0.0f;
    if (f > 0.99f) f = 0.99f;

    g.smoothDx += (targetDx - g.smoothDx) * (1.0f - f);
    g.smoothDy += (targetDy - g.smoothDy) * (1.0f - f);

    *outDx = g.smoothDx;
    *outDy = g.smoothDy;
}

// ---------------------------------------------------------------------------
// AimInit
//
//   hwnd        – game window (used for screen-size fallback)
//   vpMatrix    – current view-projection matrix (row-major float[16])
//   fovYDeg     – vertical field of view in degrees
//   smoothFactor– [0,1): 0 = instant tracking, ~0.12 is a gentle lag
//   coneRadius  – half-cone radius in pixels; pass 120 for a 240 px diameter
// ---------------------------------------------------------------------------

extern "C" void AimInit(HWND hwnd, const float vpMatrix[16],
                        float fovYDeg, float smoothFactor, float coneRadius)
{
    g = {};   // zero all state

    g.hwnd         = hwnd;
    g.fovYRad      = fovYDeg * 3.14159265f / 180.0f;
    g.smoothFactor = smoothFactor;
    g.coneRadiusPx = (coneRadius > 0.0f) ? coneRadius : 120.0f;

    for (int i = 0; i < 16; ++i) g.vp[i] = vpMatrix[i];

    // Determine screen dimensions from the window client area
    RECT rc;
    if (hwnd && GetClientRect(hwnd, &rc)) {
        g.screenW = (float)(rc.right  - rc.left);
        g.screenH = (float)(rc.bottom - rc.top);
    }
    // Fallback: assume 1920×1080
    if (g.screenW < 1.0f) g.screenW = 1920.0f;
    if (g.screenH < 1.0f) g.screenH = 1080.0f;

    g.initialised = true;
}

// ---------------------------------------------------------------------------
// AimUpdate
//
//   vpMatrix  – updated view-projection matrix for this frame
//   entities  – array of AimEntity
//   count     – number of elements in entities[]
//   result    – filled with the smoothed crosshair delta (or zeroed)
//
// Algorithm:
//   1. Project every alive entity head to screen space.
//   2. Discard anything outside the 240 px cone (radius = coneRadiusPx).
//   3. Pick the entity whose screen position is closest to the crosshair
//      (screen centre).
//   4. Compute raw delta from centre to that screen position.
//   5. Run the delta through the exponential smoother.
// ---------------------------------------------------------------------------

extern "C" void AimUpdate(const float vpMatrix[16],
                           const AimEntity *entities, int count,
                           AimResult *result)
{
    result->dx        = 0.0f;
    result->dy        = 0.0f;
    result->hasTarget = false;

    if (!g.initialised || !entities || count <= 0) return;

    // Update VP matrix
    for (int i = 0; i < 16; ++i) g.vp[i] = vpMatrix[i];

    float centreX = g.screenW * 0.5f;
    float centreY = g.screenH * 0.5f;
    float coneSq  = g.coneRadiusPx * g.coneRadiusPx;

    float bestDistSq = FLT_MAX;
    float bestSx = centreX, bestSy = centreY;
    bool  found  = false;

    for (int i = 0; i < count; ++i) {
        const AimEntity &e = entities[i];
        if (!e.alive) continue;

        float sx, sy;
        if (!WorldToScreen(e.headWorld, &sx, &sy)) continue;

        float dx = sx - centreX;
        float dy = sy - centreY;
        float dSq = dx*dx + dy*dy;

        if (dSq > coneSq)   continue;   // outside cone
        if (dSq >= bestDistSq) continue;

        bestDistSq = dSq;
        bestSx = sx;
        bestSy = sy;
        found  = true;
    }

    if (!found) {
        // Decay smoother back toward zero so the cursor doesn't drift
        SmoothToward(0.0f, 0.0f, &result->dx, &result->dy);
        // If the smoothed delta is negligible, suppress it entirely
        if (fabsf(result->dx) < 0.5f && fabsf(result->dy) < 0.5f) {
            g.smoothDx = 0.0f;
            g.smoothDy = 0.0f;
            result->dx = 0.0f;
            result->dy = 0.0f;
        }
        result->hasTarget = false;
        return;
    }

    float rawDx = bestSx - centreX;
    float rawDy = bestSy - centreY;

    SmoothToward(rawDx, rawDy, &result->dx, &result->dy);
    result->hasTarget = true;
}

// ---------------------------------------------------------------------------
// AimShutdown – nothing to free in this implementation, reserved for future
// ---------------------------------------------------------------------------

extern "C" void AimShutdown(void)
{
    g = {};
}

// ---------------------------------------------------------------------------
// Standalone smoke test  (cl /DAIM_SMOKE aim.cpp /link user32.lib gdi32.lib)
// ---------------------------------------------------------------------------

#ifdef AIM_SMOKE
#include <stdio.h>

// Minimal orthographic VP that maps world units 1:1 to NDC in a 1920×1080
// viewport (z in [0,1]).
static void MakeOrthoVP(float w, float h, float vpOut[16])
{
    // row-major identity, then set ortho scale
    for (int i = 0; i < 16; ++i) vpOut[i] = 0.0f;
    vpOut[0]  =  2.0f / w;
    vpOut[5]  =  2.0f / h;
    vpOut[10] =  1.0f;
    vpOut[15] =  1.0f;
}

int main(void)
{
    float vp[16];
    MakeOrthoVP(1920.0f, 1080.0f, vp);

    // Initialise with no real HWND; AimInit will fall back to 1920×1080
    AimInit(NULL, vp, 90.0f, 0.12f, 120.0f);

    // Entity directly in front, 10 units to the right of centre
    AimEntity ents[2] = {};
    ents[0].headWorld = { 10.0f, 0.0f, 0.5f };
    ents[0].alive     = true;
    ents[1].headWorld = { 500.0f, 500.0f, 0.5f };  // outside cone
    ents[1].alive     = true;

    printf("Frame  hasTarget  dx          dy\n");
    printf("-----  ---------  ----------  ----------\n");

    AimResult r;
    for (int frame = 0; frame < 8; ++frame) {
        AimUpdate(vp, ents, 2, &r);
        printf("%5d  %9s  %10.4f  %10.4f\n",
               frame,
               r.hasTarget ? "YES" : "NO",
               (double)r.dx,
               (double)r.dy);
    }

    AimShutdown();
    return 0;
}
#endif // AIM_SMOKE
